        Almanac::default()
    }

    #[rstest]
    // 1. Newtonian Baseline (0 error expected)
    #[case("2026-06-24T12:00:00", Box::new(NewtonianVacuum), 0.0)]
    // 2. Static Refraction Offset (Fixed 43km error)
    #[case("2026-06-25T12:00:00", Box::new(StaticOffsetModel(Vector3::new(43.0, 0.0, 0.0))), 43.0)]
    // 3. Dilatant Fluid Vacuum (Velocity-dependent shear error)
    // Note: The expected error here would normally be derived from the specific velocity 
